use core::convert::TryFrom;

use crate::{FillRule, IntRect, LengthU32, Path, PathSegment, Point, Rect};

use crate::alpha_runs::AlphaRuns;
use crate::blitter::{Blitter, FractionalClipBlitter};
use crate::color::AlphaU8;
use crate::geom::{IntRectExt, ScreenIntRect};
use crate::math::left_shift;

#[cfg(all(not(feature = "std"), feature = "no-std-float"))]
use tiny_skia_path::NoStdFloat;

/// controls how much we super-sample (when we use that scan conversion)
const SUPERSAMPLE_SHIFT: u32 = 2;

const SHIFT: u32 = SUPERSAMPLE_SHIFT;
const SCALE: u32 = 1 << SHIFT;
const MASK: u32 = SCALE - 1;

pub fn fill_path(
    path: &Path,
    fill_rule: FillRule,
    clip: &ScreenIntRect,
    blitter: &mut dyn Blitter,
) {
    fill_path_impl_with_root_clip(path, fill_rule, clip, blitter, None, false);
}

/// Fills a path while intersecting its coverage with an outer fractional
/// viewport before supersampled coverage is reduced to destination pixels.
/// `root_clip` uses destination-pixel coordinates and may extend beyond the
/// integer pixmap bounds for translated tiles.
pub fn fill_path_with_root_clip(
    path: &Path,
    fill_rule: FillRule,
    clip: &ScreenIntRect,
    blitter: &mut dyn Blitter,
    root_clip: Option<[f32; 4]>,
) {
    fill_path_impl_with_root_clip(path, fill_rule, clip, blitter, root_clip, false);
}

/// Fills a path generated by stroke expansion. Exact axis-aligned rectangle
/// coverage is enabled only here so ordinary filled paths and clip masks keep
/// the scan-converter's established coverage semantics.
pub fn fill_stroke_outline_with_root_clip(
    path: &Path,
    fill_rule: FillRule,
    clip: &ScreenIntRect,
    blitter: &mut dyn Blitter,
    root_clip: Option<[f32; 4]>,
) {
    fill_path_impl_with_root_clip(path, fill_rule, clip, blitter, root_clip, true);
}

fn fill_path_impl_with_root_clip(
    path: &Path,
    fill_rule: FillRule,
    clip: &ScreenIntRect,
    blitter: &mut dyn Blitter,
    root_clip: Option<[f32; 4]>,
    exact_stroke_rectangle: bool,
) {
    // The general path scanner approximates coverage with a 4x subpixel grid.
    // A stroked horizontal or vertical segment becomes a four-edge rectangle;
    // use the existing fixed-point rectangle rasterizer for those exact
    // axis-aligned contours so fractional stroke bounds retain their area
    // instead of being rounded to a whole supersample row.
    if exact_stroke_rectangle {
        if let Some(rect) = axis_aligned_rect(path) {
            if rect_is_strictly_inside_clip(&rect, clip, root_clip) {
                if let Some(root_clip) = root_clip {
                    let mut clipped =
                        FractionalClipBlitter::for_alpha_run_coverage(blitter, root_clip);
                    super::hairline_aa::fill_rect(&rect, clip, &mut clipped);
                } else {
                    super::hairline_aa::fill_rect(&rect, clip, blitter);
                }
                return;
            }
        }
    }

    // Unlike `path.bounds.to_rect()?.round_out()`,
    // this method rounds out first and then converts into a Rect.
    let ir = Rect::from_ltrb(
        path.bounds().left().floor(),
        path.bounds().top().floor(),
        path.bounds().right().ceil(),
        path.bounds().bottom().ceil(),
    )
    .and_then(|r| r.round_out());
    let ir = match ir {
        Some(v) => v,
        None => return,
    };

    // TODO: remove
    // If the intersection of the path bounds and the clip bounds
    // will overflow 32767 when << by SHIFT, we can't supersample,
    // so draw without antialiasing.
    let clipped_ir = match ir.intersect(&clip.to_int_rect()) {
        Some(v) => v,
        None => return,
    };
    if rect_overflows_short_shift(&clipped_ir, SHIFT as i32) != 0 {
        if let Some(root_clip) = root_clip {
            let mut clipped = FractionalClipBlitter::new(blitter, root_clip);
            super::path::fill_path(path, fill_rule, clip, &mut clipped);
        } else {
            super::path::fill_path(path, fill_rule, clip, blitter);
        }
        return;
    }

    // TODO: remove
    // Our antialiasing can't handle a clip larger than 32767.
    // TODO: skia actually limits the clip to 32767
    {
        const MAX_CLIP_COORD: u32 = 32767;
        if clip.right() > MAX_CLIP_COORD || clip.bottom() > MAX_CLIP_COORD {
            return;
        }
    }

    // TODO: SkScanClipper
    // TODO: AAA

    let root_clip = root_clip.filter(|bounds| {
        bounds[0] > clip.left() as f32
            || bounds[1] > clip.top() as f32
            || bounds[2] < clip.right() as f32
            || bounds[3] < clip.bottom() as f32
    });

    fill_path_impl(path, fill_rule, &ir, clip, root_clip, blitter)
}

fn rect_is_strictly_inside_clip(
    rect: &Rect,
    clip: &ScreenIntRect,
    root_clip: Option<[f32; 4]>,
) -> bool {
    rect.left() > clip.left() as f32
        && rect.top() > clip.top() as f32
        && rect.right() < clip.right() as f32
        && rect.bottom() < clip.bottom() as f32
        && root_clip.is_none_or(|bounds| {
            rect.left() > bounds[0]
                && rect.top() > bounds[1]
                && rect.right() < bounds[2]
                && rect.bottom() < bounds[3]
        })
}

fn axis_aligned_rect(path: &Path) -> Option<Rect> {
    let mut segments = path.segments();
    let PathSegment::MoveTo(first) = segments.next()? else {
        return None;
    };

    let mut points = [Point::zero(); 4];
    points[0] = first;
    for point in points.iter_mut().skip(1) {
        let PathSegment::LineTo(next) = segments.next()? else {
            return None;
        };
        *point = next;
    }

    match segments.next()? {
        PathSegment::Close => {}
        PathSegment::LineTo(last) if last.x == first.x && last.y == first.y => {
            if !matches!(segments.next()?, PathSegment::Close) {
                return None;
            }
        }
        _ => return None,
    }
    if segments.next().is_some() {
        return None;
    }

    let left = points.iter().map(|p| p.x).fold(f32::INFINITY, f32::min);
    let right = points.iter().map(|p| p.x).fold(f32::NEG_INFINITY, f32::max);
    let top = points.iter().map(|p| p.y).fold(f32::INFINITY, f32::min);
    let bottom = points.iter().map(|p| p.y).fold(f32::NEG_INFINITY, f32::max);
    if !left.is_finite() || !top.is_finite() || right <= left || bottom <= top {
        return None;
    }

    let mut corner_mask = 0_u8;
    for index in 0..points.len() {
        let current = points[index];
        let next = points[(index + 1) % points.len()];
        if current == next || (current.x != next.x && current.y != next.y) {
            return None;
        }

        let horizontal = if current.x == left {
            0
        } else if current.x == right {
            1
        } else {
            return None;
        };
        let vertical = if current.y == top {
            0
        } else if current.y == bottom {
            1
        } else {
            return None;
        };
        let corner = 1 << (vertical * 2 + horizontal);
        if corner_mask & corner != 0 {
            return None;
        }
        corner_mask |= corner;
    }

    if corner_mask != 0b1111 {
        return None;
    }

    Rect::from_ltrb(left, top, right, bottom)
}

// Would any of the coordinates of this rectangle not fit in a short,
// when left-shifted by shift?
fn rect_overflows_short_shift(rect: &IntRect, shift: i32) -> i32 {
    debug_assert!(overflows_short_shift(8191, shift) == 0);
    debug_assert!(overflows_short_shift(8192, shift) != 0);
    debug_assert!(overflows_short_shift(32767, 0) == 0);
    debug_assert!(overflows_short_shift(32768, 0) != 0);

    // Since we expect these to succeed, we bit-or together
    // for a tiny extra bit of speed.
    overflows_short_shift(rect.left(), shift)
        | overflows_short_shift(rect.top(), shift)
        | overflows_short_shift(rect.right(), shift)
        | overflows_short_shift(rect.bottom(), shift)
}

fn overflows_short_shift(value: i32, shift: i32) -> i32 {
    let s = 16 + shift;
    (left_shift(value, s) >> s) - value
}

fn fill_path_impl(
    path: &Path,
    fill_rule: FillRule,
    bounds: &IntRect,
    clip: &ScreenIntRect,
    root_clip: Option<[f32; 4]>,
    blitter: &mut dyn Blitter,
) {
    // TODO: MaskSuperBlitter

    // TODO: 15% slower than skia, find out why
    let mut blitter = match SuperBlitter::new(bounds, clip, root_clip, blitter) {
        Some(v) => v,
        None => return, // clipped out, nothing else to do
    };

    let path_contained_in_clip = if let Some(bounds) = bounds.to_screen_int_rect() {
        clip.contains(&bounds)
    } else {
        // If bounds cannot be converted into ScreenIntRect,
        // the path is out of clip.
        false
    };

    super::path::fill_path_impl(
        path,
        fill_rule,
        clip,
        bounds.top(),
        bounds.bottom(),
        SHIFT as i32,
        path_contained_in_clip,
        &mut blitter,
    );
}

struct BaseSuperBlitter<'a> {
    real_blitter: &'a mut dyn Blitter,

    /// Current y coordinate, in destination coordinates.
    curr_iy: i32,
    /// Widest row of region to be blitted, in destination coordinates.
    width: LengthU32,
    /// Leftmost x coordinate in any row, in destination coordinates.
    left: u32,
    /// Leftmost x coordinate in any row, in supersampled coordinates.
    super_left: u32,

    /// Current y coordinate in supersampled coordinates.
    curr_y: i32,
    /// Initial y coordinate (top of bounds).
    top: i32,
}

impl<'a> BaseSuperBlitter<'a> {
    fn new(
        bounds: &IntRect,
        clip_rect: &ScreenIntRect,
        blitter: &'a mut dyn Blitter,
    ) -> Option<Self> {
        let sect = bounds
            .intersect(&clip_rect.to_int_rect())?
            .to_screen_int_rect()?;
        Some(BaseSuperBlitter {
            real_blitter: blitter,
            curr_iy: sect.top() as i32 - 1,
            width: sect.width_safe(),
            left: sect.left(),
            super_left: sect.left() << SHIFT,
            curr_y: (sect.top() << SHIFT) as i32 - 1,
            top: sect.top() as i32,
        })
    }
}

struct SuperBlitter<'a> {
    base: BaseSuperBlitter<'a>,
    runs: AlphaRuns,
    offset_x: usize,
    root_clip: Option<[f32; 4]>,
}

impl<'a> SuperBlitter<'a> {
    fn new(
        bounds: &IntRect,
        clip_rect: &ScreenIntRect,
        root_clip: Option<[f32; 4]>,
        blitter: &'a mut dyn Blitter,
    ) -> Option<Self> {
        let base = BaseSuperBlitter::new(bounds, clip_rect, blitter)?;
        let runs_width = base.width;
        Some(SuperBlitter {
            base,
            runs: AlphaRuns::new(runs_width),
            offset_x: 0,
            root_clip,
        })
    }

    /// Once `runs` contains a complete supersampled row, flush() blits
    /// it out through the wrapped blitter.
    fn flush(&mut self) {
        if self.base.curr_iy >= self.base.top {
            if !self.runs.is_empty() {
                self.base.real_blitter.blit_anti_h(
                    self.base.left,
                    u32::try_from(self.base.curr_iy).unwrap(),
                    &mut self.runs.alpha,
                    &mut self.runs.runs,
                );
                self.runs.reset(self.base.width);
                self.offset_x = 0;
            }

            self.base.curr_iy = self.base.top - 1;
        }
    }
}

impl Drop for SuperBlitter<'_> {
    fn drop(&mut self) {
        self.flush();
    }
}

impl Blitter for SuperBlitter<'_> {
    /// Blits a row of pixels, with location and width specified
    /// in supersampled coordinates.
    fn blit_h(&mut self, mut x: u32, y: u32, mut width: LengthU32) {
        if let Some(root_clip) = self.root_clip {
            self.blit_h_with_root_clip(x, y, width, root_clip);
            return;
        }

        let iy = (y >> SHIFT) as i32;
        debug_assert!(iy >= self.base.curr_iy);

        // hack, until I figure out why my cubics (I think) go beyond the bounds
        match x.checked_sub(self.base.super_left) {
            Some(n) => x = n,
            None => {
                width = LengthU32::new(x + width.get()).unwrap();
                x = 0;
            }
        }

        debug_assert!(y as i32 >= self.base.curr_y);
        if self.base.curr_y != y as i32 {
            self.offset_x = 0;
            self.base.curr_y = y as i32;
        }

        if iy != self.base.curr_iy {
            // new scanline
            self.flush();
            self.base.curr_iy = iy;
        }

        let start = x;
        let stop = x + width.get();

        debug_assert!(stop > start);
        // integer-pixel-aligned ends of blit, rounded out
        let mut fb = start & MASK;
        let mut fe = stop & MASK;
        let mut n: i32 = (stop as i32 >> SHIFT) - (start as i32 >> SHIFT) - 1;

        if n < 0 {
            fb = fe - fb;
            n = 0;
            fe = 0;
        } else {
            if fb == 0 {
                n += 1;
            } else {
                fb = SCALE - fb;
            }
        }

        let max_value = u8::try_from((1 << (8 - SHIFT)) - (((y & MASK) + 1) >> SHIFT)).unwrap();
        self.offset_x = self.runs.add(
            x >> SHIFT,
            coverage_to_partial_alpha(fb),
            n as usize,
            coverage_to_partial_alpha(fe),
            max_value,
            self.offset_x,
        );
    }
}

impl SuperBlitter<'_> {
    fn blit_h_with_root_clip(&mut self, x: u32, y: u32, width: LengthU32, root_clip: [f32; 4]) {
        let iy = (y >> SHIFT) as i32;
        debug_assert!(iy >= self.base.curr_iy);

        debug_assert!(y as i32 >= self.base.curr_y);
        if self.base.curr_y != y as i32 {
            self.offset_x = 0;
            self.base.curr_y = y as i32;
        }

        if iy != self.base.curr_iy {
            self.flush();
            self.base.curr_iy = iy;
        }

        let scale = f64::from(SCALE);
        let row_top = f64::from(y) / scale;
        let row_bottom = f64::from(y + 1) / scale;
        let clip_top = f64::from(root_clip[1]);
        let clip_bottom = f64::from(root_clip[3]);
        let overlap_y =
            (row_bottom.min(clip_bottom) - row_top.max(clip_top)).clamp(0.0, 1.0 / scale);
        if overlap_y == 0.0 {
            return;
        }

        let original_row_weight =
            u32::from(u8::try_from((1 << (8 - SHIFT)) - (((y & MASK) + 1) >> SHIFT)).unwrap());
        let clipped_row_weight = (f64::from(original_row_weight) * overlap_y * scale).round();
        if clipped_row_weight <= 0.0 {
            return;
        }
        let row_weight = u8::try_from(clipped_row_weight as u32).unwrap_or(u8::MAX);

        let span_start = f64::from(x) / scale;
        let span_stop = (f64::from(x) + f64::from(width.get())) / scale;
        let start = span_start.max(f64::from(root_clip[0]));
        let stop = span_stop.min(f64::from(root_clip[2]));
        if stop <= start {
            return;
        }

        let start =
            (start - f64::from(self.base.left)).clamp(0.0, f64::from(self.base.width.get()));
        let stop = (stop - f64::from(self.base.left)).clamp(0.0, f64::from(self.base.width.get()));
        if stop <= start {
            return;
        }

        let first = start.floor() as u32;
        let first_end = f64::from(first + 1);
        let full_stop = stop.floor();
        let start_coverage = if start > f64::from(first) {
            (first_end - start).clamp(0.0, 1.0)
        } else {
            0.0
        };
        let stop_coverage = stop - full_stop;

        if stop <= first_end {
            let coverage = (stop - start).clamp(0.0, 1.0);
            let alpha = area_to_partial_alpha(coverage, row_weight);
            if alpha != 0 {
                self.offset_x = self.runs.add(first, alpha, 0, 0, row_weight, self.offset_x);
            }
            return;
        }

        let middle_start = if start_coverage > 0.0 {
            first + 1
        } else {
            first
        };
        let middle_end = full_stop as u32;
        let middle_count = middle_end.saturating_sub(middle_start) as usize;
        let start_alpha = area_to_partial_alpha(start_coverage, row_weight);
        let stop_alpha = area_to_partial_alpha(stop_coverage, row_weight);
        self.offset_x = self.runs.add(
            first,
            start_alpha,
            middle_count,
            stop_alpha,
            row_weight,
            self.offset_x,
        );
    }
}

fn area_to_partial_alpha(horizontal_coverage: f64, row_weight: u8) -> AlphaU8 {
    (horizontal_coverage.clamp(0.0, 1.0) * f64::from(row_weight)).round() as u8
}

// coverage_to_partial_alpha() is being used by AlphaRuns, which
// *accumulates* SCALE pixels worth of "alpha" in [0,(256/SCALE)]
// to produce a final value in [0, 255] and handles clamping 256->255
// itself, with the same (alpha - (alpha >> 8)) correction as
// coverage_to_exact_alpha().
fn coverage_to_partial_alpha(mut aa: u32) -> AlphaU8 {
    aa <<= 8 - 2 * SHIFT;
    aa as AlphaU8
}
